-- Resultados oficiais das Eleicoes Gerais 2026 (1o turno, 100% das secoes).
-- 1) Conserta o cargo TROCADO dos deputados 2026 (o seed de ago/2026 gravou
--    DepFed como DepEst e vice-versa) casando numero+nome de urna do TSE;
-- 2) votos nominais por municipio (Gov/Sen/DepFed/DepEst);
-- 3) eleito=1 apenas nos titulares eleitos (chapas de Senador repetem o
--    numero entre titular e suplentes, por isso o nome entra no casamento).
-- Duplicatas de candidato recebem MIN(id). Idempotente (DELETE previo).

DELETE FROM Resultado WHERE candidatoId IN (SELECT ca.id FROM Candidato ca JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id WHERE e.ano = 2026);

CREATE TEMP TABLE tmp_res26 (cargo TEXT, slug TEXT, numero INTEGER, cod TEXT, mun TEXT, nomeTse TEXT, votos INTEGER);

CREATE TEMP TABLE tmp_roster AS SELECT DISTINCT cargo, numero, nomeTse FROM tmp_res26;

-- Conserto do cargo trocado: todo candidato 2026 de deputado cujo
-- numero+nome casa com o cargo CERTO do TSE vai para esse cargo
-- (vale tambem para as copias duplicadas).
UPDATE Candidato SET cargoId = (
  SELECT c.id FROM Cargo c JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome = 'Deputado Federal'
) WHERE id IN (
  SELECT ca.id FROM Candidato ca JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome IN ('Deputado Federal','Deputado Estadual')
    AND EXISTS (SELECT 1 FROM tmp_roster tr WHERE tr.cargo = 'Deputado Federal'
                AND tr.numero = ca.numero AND UPPER(tr.nomeTse) = UPPER(ca.nome))
);
UPDATE Candidato SET cargoId = (
  SELECT c.id FROM Cargo c JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome = 'Deputado Estadual'
) WHERE id IN (
  SELECT ca.id FROM Candidato ca JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome IN ('Deputado Federal','Deputado Estadual')
    AND EXISTS (SELECT 1 FROM tmp_roster tr WHERE tr.cargo = 'Deputado Estadual'
                AND tr.numero = ca.numero AND UPPER(tr.nomeTse) = UPPER(ca.nome))
);

-- Mapa candidato: cargo+numero+nome (MIN id nas duplicatas); fallback por
-- numero apenas nos majoritarios (nos deputados o nome e obrigatorio).
CREATE TEMP TABLE tmp_cand AS SELECT DISTINCT cargo, numero, nomeTse FROM tmp_res26;
ALTER TABLE tmp_cand ADD COLUMN candId TEXT;
UPDATE tmp_cand SET candId = (
  SELECT MIN(ca.id) FROM Candidato ca
  JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome = tmp_cand.cargo AND ca.numero = tmp_cand.numero
    AND UPPER(ca.nome) = UPPER(tmp_cand.nomeTse)
);
UPDATE tmp_cand SET candId = (
  SELECT MIN(ca.id) FROM Candidato ca
  JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome = tmp_cand.cargo AND ca.numero = tmp_cand.numero
) WHERE candId IS NULL AND cargo IN ('Governador','Senador');

-- Fallback dos deputados por NUMERO apenas: federal tem 4 digitos e
-- estadual 5, entao o numero sozinho ja identifica a casa (zero colisao
-- nos arquivos do TSE) -- cobre nome de urna que mudou entre o registro
-- e a eleicao (ex.: PAULO HENRIQUE -> PAULO HENRIQUE GOMES).
UPDATE tmp_cand SET candId = (
  SELECT MIN(ca.id) FROM Candidato ca
  JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome IN ('Deputado Federal','Deputado Estadual')
    AND ca.numero = tmp_cand.numero
) WHERE candId IS NULL AND cargo IN ('Deputado Federal','Deputado Estadual');

-- E move essas copias para o cargo certo (mesmo criterio do numero).
UPDATE Candidato SET cargoId = (
  SELECT c.id FROM Cargo c JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome = 'Deputado Federal'
) WHERE id IN (
  SELECT ca.id FROM Candidato ca JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome = 'Deputado Estadual'
    AND EXISTS (SELECT 1 FROM tmp_roster tr WHERE tr.cargo = 'Deputado Federal' AND tr.numero = ca.numero)
);
UPDATE Candidato SET cargoId = (
  SELECT c.id FROM Cargo c JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome = 'Deputado Estadual'
) WHERE id IN (
  SELECT ca.id FROM Candidato ca JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome = 'Deputado Federal'
    AND EXISTS (SELECT 1 FROM tmp_roster tr WHERE tr.cargo = 'Deputado Estadual' AND tr.numero = ca.numero)
);

SELECT 'r26-' || t.slug || '-' || t.numero || '-' || t.cod, tc.candId, m.id, 1, t.votos, datetime('now')
FROM tmp_res26 t
JOIN tmp_cand tc ON tc.cargo = t.cargo AND tc.numero = t.numero AND tc.nomeTse = t.nomeTse
JOIN Municipio m ON m.nome = t.mun
WHERE tc.candId IS NOT NULL;

CREATE TEMP TABLE tmp_eleitos (cargo TEXT, numero INTEGER, nomeTse TEXT);


UPDATE Candidato SET eleito = 0 WHERE id IN (
  SELECT ca.id FROM Candidato ca JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome IN ('Governador','Senador','Deputado Federal','Deputado Estadual')
);
UPDATE Candidato SET eleito = 1 WHERE id IN (
  SELECT tc.candId FROM tmp_cand tc
  JOIN tmp_eleitos te ON te.cargo = tc.cargo AND te.numero = tc.numero AND te.nomeTse = tc.nomeTse
  WHERE tc.candId IS NOT NULL
);

DROP TABLE tmp_res26;
DROP TABLE tmp_roster;
DROP TABLE tmp_cand;
DROP TABLE tmp_eleitos;
